class BootstrapPopoverManager{constructor(t=".bs-popover-trigger",e={}){this.triggerSelector=t,this.currentPopover=null,this.defaultOptions={container:".tour-difficulties",html:!0,sanitize:!1,placement:"top",trigger:"click",closeButtonHtml:'<button type="button" class="btn-close position-absolute top-0 end-0 mt-1 me-1" aria-label="Close"></button>',...e}}init(){document.addEventListener("DOMContentLoaded",()=>{this.initializePopovers()})}initializePopovers(){const t=document.querySelectorAll(this.triggerSelector);for(const e of t)this.setupPopover(e)}setupPopover(t){t.addEventListener("show.bs.popover",()=>{this.handlePopoverShow(t)});const e=new bootstrap.Popover(t,{...this.defaultOptions,title:()=>this.getPopoverTitle(t),content:t.dataset.bsContent});t.addEventListener("shown.bs.popover",()=>{this.handlePopoverShown(e)})}handlePopoverShow(t){const e=bootstrap.Popover.getOrCreateInstance(t);null!==this.currentPopover&&this.currentPopover!==e&&this.currentPopover.hide(),this.currentPopover=e}getPopoverTitle(t){return t.dataset.bsTitle.replace("[br]","<br>")+this.defaultOptions.closeButtonHtml}handlePopoverShown(t){const e=document.querySelector(".popover .btn-close");e&&e.addEventListener("click",()=>{t.hide()},{once:!0})}destroy(){const t=document.querySelectorAll(this.triggerSelector);for(const e of t){const t=bootstrap.Popover.getInstance(e);t&&t.dispose()}this.currentPopover=null}}